(() => {
  'use strict';

  const finishNames = { light: 'Natural oak', dark: 'Smoked oak', smoked: 'Smoked oak' };
  const day = value => new Intl.DateTimeFormat('en-GB', { day: 'numeric', month: 'long', timeZone: 'UTC' }).format(new Date(`${value}T12:00:00Z`));
  const addDays = (value, count) => {
    const date = new Date(`${value}T12:00:00Z`);
    date.setUTCDate(date.getUTCDate() + count);
    return date.toISOString().slice(0, 10);
  };
  const daysBetween = (start, end) => Math.round((new Date(`${end}T12:00:00Z`) - new Date(`${start}T12:00:00Z`)) / 86400000);
  const signature = s => JSON.stringify({ pieces: [...s.pinned].sort().map(id => { const c = s.sourcing?.configurations?.[id] || {}; return [id, s.quantities[id] || 1, c.finish || (id === 'chair' ? s.studioFinish : 'light'), Boolean(c.com), c.comNote || '', c.customBrief || '']; }), studioFinish: s.studioFinish });
  const materialName = (item, value) => item.id === 'chair' ? `${finishNames[value] || 'Natural oak'} / natural linen` : item.id === 'table' ? (value === 'dark' ? 'Smoked walnut' : 'Natural walnut / clear oil') : item.id === 'lamp' ? (value === 'dark' ? 'Aged bronze' : 'Brushed bronze') : (value === 'dark' ? 'Warm stone wool' : 'Natural linen');
  const snapshot = ctx => ({ pieces: ctx.selected().map(item => { const config = ctx.state.sourcing?.configurations?.[item.id] || {}; return { id: item.id, name: item.name, quantity: ctx.state.quantities[item.id] || 1, material: materialName(item, item.id === 'chair' ? ctx.state.studioFinish : config.finish || 'light'), com: Boolean(config.com), customBrief: config.customBrief || '' }; }), finish: ctx.state.pinned.includes('chair') ? ctx.state.studioFinish : null });
  const initials = ctx => {
    const c = ctx.state.core ||= {};
    c.projectPanel ||= 'room';
    c.brief ||= { scope: 'A living room for reading, conversation and an open view to the lake.', keep: 'Keep the wool rug and the clear view through the windows.', living: 'Two people most days; room for six when family visits. A good reading light matters.', target: '2026-11-18', decisionLead: 'Nora Ellis', reviewer: 'Evan Ellis', note: 'Confirm the physical finish sample before the workshop instruction is released.' };
    const baseline = { ...ctx.state, pinned: ['chair', 'table', 'sofa'], quantities: { chair: 2, table: 1, sofa: 1, lamp: 1 }, studioFinish: 'light', sourcing: {} };
    c.plans ||= [{ version: 2, title: 'A-01 · Living room direction', state: 'issued', date: '20 October 2026', snapshot: snapshot({ ...ctx, state: baseline, selected: () => ctx.items.filter(item => baseline.pinned.includes(item.id)) }), signature: signature(baseline) }];
    c.record ||= [];
    c.authorityAssigned ??= false;
    c.approvalHistory ||= [];
    c.agreement ||= { scope: 'Living room direction, furniture specifications, workshop coordination and one installation visit.', hourly: 150, ceiling: 4500, retainer: 1500, clientLinked: true, feeVisible: true, status: 'draft', message: 'Nora and Evan, here is the scope and fee basis for the living room. Let me know if you would like to talk through any part.' };
    c.schedulePanel ||= 'plan';
    c.approvalDue ||= '2026-10-28';
    c.openItems ||= [{ id: 'lead-time', title: 'Confirm workshop timing against the install target', owner: 'Leah', date: '2026-10-26', done: false }];
    c.punch ||= [{ id: 'glides', title: 'Check the chair glides on the existing rug', date: '2026-11-18', hours: 0.25, done: false }, { id: 'lamp', title: 'Set the reading lamp height with Nora', date: '2026-11-18', hours: 0.25, done: false }];
    return c;
  };
  const on = (ctx, selector, event, action) => ctx.root.querySelectorAll(selector).forEach(node => node.addEventListener(event, action));
  const formData = event => { event.preventDefault(); return new FormData(event.currentTarget); };
  const write = (ctx, mutate, message) => { ctx.update(s => mutate(s, s.core)); if (message) ctx.feedback(message); };
  const record = (s, type, text, view) => {
    const entry = { id: String(Date.now()), date: '21 October 2026', type, text, view };
    s.activity = [entry, ...(s.activity || [])];
    s.core.record = [entry, ...(s.core.record || [])];
  };
  const latestIssued = c => [...c.plans].reverse().find(plan => plan.state === 'issued');
  const revision = n => String.fromCharCode(64 + n);
  const title = (eyebrow, heading, intro) => `<header class="view-head core-head"><div><p class="eyebrow">${eyebrow}</p><h1 tabindex="-1">${heading}</h1></div><p class="lede">${intro}</p></header>`;
  const panelNav = (active, entries, attribute) => `<nav class="tabs core-panel-nav" aria-label="${attribute === 'data-project-panel' ? 'Project pages' : 'Schedule pages'}">${entries.map(([id, label]) => `<button type="button" ${attribute}="${id}" aria-pressed="${active === id}">${label}</button>`).join('')}</nav>`;
  const downloadText = (name, text) => {
    const url = URL.createObjectURL(new Blob([text], { type: 'text/plain;charset=utf-8' }));
    const a = document.createElement('a'); a.href = url; a.download = name; a.click();
    setTimeout(() => URL.revokeObjectURL(url), 1000);
  };

  function roomPage(ctx, c) {
    const e = ctx.escape;
    const item = ctx.items.find(piece => piece.id === ctx.state.selectedPiece) || ctx.items[0];
    const positions = { chair: [23, 64], table: [54, 63], sofa: [72, 51], lamp: [94, 33] };
    const status = !ctx.state.pinned.includes(item.id) ? 'Reference only · not in the selection' : item.id === 'chair' && !ctx.state.clientFinish ? 'Design approval not yet recorded' : ctx.state.designApproved ? 'Current design edition approved' : 'Current design review not complete';
    return `<div class="core-room-spread">
      <figure class="core-room-plate"><div class="core-room-picture"><img src="assets/room.png" alt="Concept illustration of the living room, with an oak chair, walnut table, linen sofa and bronze floor lamp." width="1536" height="1024">${ctx.items.map(piece => `<button type="button" class="core-pin" data-core-piece="${piece.id}" aria-label="Inspect ${e(piece.name)}" aria-pressed="${piece.id === item.id}" style="left:${positions[piece.id][0]}%;top:${positions[piece.id][1]}%">${e(piece.number)}</button>`).join('')}</div><figcaption><span>Room direction · concept illustration</span><span>Figures open the working record</span></figcaption></figure>
      <aside class="core-room-margin"><span class="core-figure">${e(item.number)}</span><p class="annotation">In the room</p><h2>${e(item.name)}</h2><p class="quiet">${e(item.material)}</p><p class="status ${ctx.state.designApproved ? 'good' : 'wait'}">${status}</p><blockquote>“The grain, the linen and the view should feel at ease with one another.”</blockquote><p class="small quiet">Leah’s note on the direction</p><dl class="core-facts"><div><dt>Made with</dt><dd>${e(item.maker)}</dd></div><div><dt>In this room</dt><dd>${ctx.state.pinned.includes(item.id) ? `${ctx.state.quantities[item.id] || 1} selected` : 'Not selected'}</dd></div></dl><a class="button" href="${ctx.link('piece', { piece: item.id })}" data-go="piece" data-piece="${item.id}">Open the piece proof <span aria-hidden="true">↗</span></a><p class="small quiet core-after-action">A finish preference, a design approval and permission to purchase are separate acts.</p></aside>
    </div><div class="core-object-index" role="group" aria-label="Room figures">${ctx.items.map(piece => `<button type="button" data-core-piece="${piece.id}" aria-pressed="${piece.id === item.id}"><span>${e(piece.number)}</span><strong>${e(piece.name)}</strong><small>${ctx.state.pinned.includes(piece.id) ? `${ctx.state.quantities[piece.id] || 1} selected` : 'Reference only'}</small></button>`).join('')}</div>
    <div class="core-room-bottom"><div><h2>The room, as agreed.</h2><p>${e(c.brief.scope)}</p></div><div><p class="annotation">The next handoff</p><p>${ctx.state.designApproved ? 'The design is agreed. Purchasing still needs its own authorization and release review.' : ctx.state.clientFinish ? 'The last approved chair finish is on the record. The current design still needs a formal review.' : 'Read the chair’s working specification, then prepare an issued edition for Nora and Evan to review.'}</p><a class="text-button" href="${ctx.link('approvals')}" data-go="approvals">Open the approval record ↗</a></div></div>`;
  }

  function briefPage(ctx, c) {
    const e = ctx.escape;
    return `<div class="wide-spread core-brief-layout"><form id="core-brief-form" class="paper core-brief-paper"><div class="core-section-head"><h2>The brief</h2><span class="annotation">Living room / in scope</span></div><label class="field">What this room needs to do<textarea name="scope" rows="3" required>${e(c.brief.scope)}</textarea></label><div class="form-grid"><label class="field">Furnishings budget, USD<input type="number" min="1" step="1" name="budget" value="${ctx.state.budget}" required></label><label class="field">Held installation target<input type="date" name="target" value="${e(c.brief.target)}" readonly></label></div><p class="small quiet">The furnishings budget excludes design services. The target is held in this example; workshop and delivery confirmation are still required.</p><label class="field">What stays<textarea name="keep" rows="2">${e(c.brief.keep)}</textarea></label><label class="field">How Nora and Evan live<textarea name="living" rows="3">${e(c.brief.living)}</textarea></label><button type="submit" class="button">Save the brief</button></form><aside class="margin-note core-brief-margin"><p class="annotation">The people behind the room</p><h2>Nora &amp; Evan Ellis</h2><dl class="core-facts"><div><dt>Decision lead</dt><dd>Nora Ellis</dd></div><div><dt>Also reviews</dt><dd>Evan Ellis</dd></div><div><dt>Studio</dt><dd>Leah / Middle West Studio</dd></div></dl><p>The brief keeps a household preference distinct from the person who can approve an issued design.</p><a class="text-button" href="${ctx.link('people')}" data-go="people">Open the project directory ↗</a><details class="details core-private"><summary>Private studio note</summary><form id="core-private-form"><label class="field">For the studio<textarea name="note" rows="4">${e(c.brief.note)}</textarea></label><button type="submit" class="button secondary">Save studio note</button></form></details><button type="button" class="text-button" data-export-brief>Download the shared brief ↗</button></aside></div>`;
  }

  function planPage(ctx, c) {
    const e = ctx.escape;
    const plan = c.plans[c.plans.length - 1];
    return `<div class="spread core-plan-layout"><article class="paper core-plan-paper"><div class="core-section-head"><div><p class="annotation">Drawing sets</p><h2>${e(plan.title)}</h2></div><span class="core-revision">${revision(plan.version)}</span></div><div class="core-drawing" role="img" aria-label="Illustrative living room plan showing a sofa, two chairs and a table; not a measured construction drawing"><svg viewBox="0 0 680 390" aria-hidden="true"><path class="core-wall" d="M70 320V60H600V320H240M170 320H70"/><path d="M70 68H600M590 60V320M170 320V250A70 70 0 0 1 240 320M125 60V68M530 60V68"/><path d="M155 56H475M155 72H475"/><rect x="345" y="106" width="180" height="72" rx="4"/><path d="M355 106V178M435 106V178M515 106V178"/><rect x="145" y="175" width="62" height="70" rx="3"/><path d="M155 185H197V227H155Z"/><rect x="250" y="245" width="62" height="70" rx="3" transform="rotate(-18 281 280)"/><ellipse cx="326" cy="218" rx="63" ry="36"/><circle cx="551" cy="133" r="15"/><path d="M84 351H585M84 345V357M585 345V357"/><text x="335" y="376" text-anchor="middle">Illustrative plan · dimensions require verification</text><text x="112" y="110">Living room</text><text x="112" y="131">Lake Mendota House</text></svg></div><div class="core-plan-caption"><span>Rev ${revision(plan.version)} / ${plan.state === 'issued' ? 'Issued ' + e(plan.date) : 'Working draft'}</span><span>Sketch preview · not measured evidence</span></div><div class="core-plan-editions">${c.plans.map(p => `<div><strong>Rev ${revision(p.version)}</strong><span>${e(p.title)}</span><span class="status ${p.state === 'issued' ? 'good' : 'wait'}">${p.state === 'issued' ? 'Issued' : 'Draft'}</span></div>`).join('')}</div></article><aside class="margin-note"><p class="annotation">Keep the edition clear</p><h2>${plan.state === 'issued' ? 'The issued copy.' : 'A new drawing, still in draft.'}</h2><p>Approval requests bind to an issued edition. A working revision cannot replace the evidence behind a decision.</p>${plan.state === 'draft' ? `<button type="button" class="button" data-issue-plan>Issue Rev ${revision(plan.version)} for review</button>` : `<details class="details"><summary>File the next revision</summary><form id="core-plan-form"><label class="field">Drawing title<input name="title" value="A-01 · Living room direction" required></label><p class="small quiet">Rev ${revision(plan.version + 1)} starts as a draft. The previous issued edition stays in the record.</p><button type="submit" class="button secondary">Create revision ${revision(plan.version + 1)}</button></form></details>`}<div class="core-source-note"><h3>Measured room evidence</h3><p class="status wait">No verified scan attached</p><p class="small">The room illustration and this sketch are direction references. A measured Room File would carry its scan date, verification status and drawing sheets separately.</p></div><a class="text-button" href="${ctx.link('approvals')}" data-go="approvals">Open the approval record ↗</a></aside></div>`;
  }

  function recordPage(ctx, c) {
    const e = ctx.escape;
    const initial = [{ date: '12 October 2026', text: 'The room direction was agreed for development: oak, linen, walnut and an open view to the water.' }, { date: '16 October 2026', text: 'The furniture selection was brought together for the living room.' }, { date: '20 October 2026', text: 'A-01, revision B was issued as the room-direction reference.' }];
    return `<div class="spread"><article class="core-record-paper"><h2>The record stays with the room.</h2><p class="quiet core-record-intro">An authored note, an issued edition and a client decision each keep their own place.</p><ol class="core-record-list">${[...c.record, ...initial].map(entry => `<li><time>${e(entry.date)}</time><p>${e(entry.text)}</p>${entry.view ? `<a class="text-button" href="${ctx.link(entry.view)}" data-go="${e(entry.view)}">Open the record ↗</a>` : ''}</li>`).join('')}</ol></article><aside class="margin-note"><p class="annotation">Current standing</p><h2>${ctx.state.designApproved ? 'Design agreed.' : 'Review still open.'}</h2><dl class="core-facts"><div><dt>Last approved finish</dt><dd>${ctx.state.clientFinish ? finishNames[ctx.state.clientFinish] : 'Not recorded'}</dd></div><div><dt>Design approval</dt><dd>${ctx.state.designApproved ? 'Current edition approved' : 'Not approved for the current selection'}</dd></div><div><dt>Purchasing</dt><dd>${ctx.state.purchaseAuthorized ? 'Separately authorized' : 'Not authorized by this design record'}</dd></div></dl><a class="text-button" href="${ctx.link('inbox')}" data-go="inbox">Open studio correspondence ↗</a></aside></div>`;
  }

  function installPage(ctx, c) {
    const open = c.punch.filter(task => !task.done).length;
    return `<div class="spread"><article class="paper"><p class="annotation">At the house / ${day(c.brief.target)}</p><h2>The last details.</h2><p class="lede">${open ? `${open} installation checks remain.` : 'The installation checks in this sample are complete.'}</p><div class="core-install-preview"><img src="assets/room.png" alt="The illustrated room direction for reference during installation" width="1536" height="1024"><p class="small quiet">Direction reference · not an installation photograph</p></div><ul class="rule-list">${c.punch.map(task => `<li class="rule-row"><span>${ctx.escape(task.title)}</span><span class="status ${task.done ? 'good' : 'wait'}">${task.done ? 'Done' : 'Open'}</span></li>`).join('')}</ul><button type="button" class="button secondary" data-open-install>Open the installation punch list</button></article><aside class="margin-note"><h2>Close with evidence.</h2><p>Finish the installation checks, attach the final room record, and settle the account before closing the project.</p><p class="status wait">Project closeout has not been recorded.</p><a class="text-button" href="${ctx.link('accounts')}" data-go="accounts">Read the project account ↗</a></aside></div>`;
  }

  RoomProof.register('project', {
    title: 'The project', family: 'project',
    render(ctx) {
      const c = initials(ctx);
      const pages = { room: roomPage, brief: briefPage, plans: planPage, record: recordPage, install: installPage };
      return title('Middle West Studio / Project 024', 'Lake Mendota House.', `The living room for Nora and Evan Ellis.<br>Installation target ${day(c.brief.target)}.`) + panelNav(c.projectPanel, [['room', 'The room'], ['brief', 'The brief'], ['plans', 'Drawing sets'], ['record', 'The record'], ['install', 'At the house']], 'data-project-panel') + (pages[c.projectPanel] || roomPage)(ctx, c);
    },
    bind(ctx) {
      on(ctx, '[data-project-panel]', 'click', event => write(ctx, (s, c) => { c.projectPanel = event.currentTarget.dataset.projectPanel; }));
      on(ctx, '[data-core-piece]', 'click', event => write(ctx, s => { s.selectedPiece = event.currentTarget.dataset.corePiece; }));
      on(ctx, '#core-brief-form', 'submit', event => { const d = formData(event); write(ctx, (s, c) => { c.brief.scope = d.get('scope').trim(); c.brief.keep = d.get('keep').trim(); c.brief.living = d.get('living').trim(); s.budget = Number(d.get('budget')); record(s, 'note', 'The living room brief and furnishings budget were updated.', 'project'); }, 'The brief is saved.'); });
      on(ctx, '#core-private-form', 'submit', event => { const d = formData(event); write(ctx, (s, c) => { c.brief.note = d.get('note').trim(); }, 'Private studio note saved. It is excluded from the shared brief.'); });
      on(ctx, '[data-export-brief]', 'click', () => { const c = initials(ctx); downloadText('Lake-Mendota-shared-brief.txt', `Lake Mendota House\nLiving room\n\n${c.brief.scope}\n\nWhat stays\n${c.brief.keep}\n\nHow they live\n${c.brief.living}\n\nFurnishings budget: ${ctx.money(ctx.state.budget)} (design services excluded)\nInstallation target: ${day(c.brief.target)}\nDecision lead: Nora Ellis\nAlso reviews: Evan Ellis\n\nFictional review sample.`); ctx.feedback('The shared brief was downloaded without the private studio note.'); });
      on(ctx, '#core-plan-form', 'submit', event => { const d = formData(event); write(ctx, (s, c) => { const version = c.plans[c.plans.length - 1].version + 1; c.plans.push({ version, title: d.get('title').trim(), state: 'draft', date: '21 October 2026' }); record(s, 'note', `Drawing revision ${revision(version)} was opened as a working draft.`, 'project'); }, 'The new revision is a draft. The previous issued copy is retained.'); });
      on(ctx, '[data-issue-plan]', 'click', () => { const snap = snapshot(ctx); write(ctx, (s, c) => { const plan = c.plans[c.plans.length - 1]; plan.state = 'issued'; plan.snapshot = snap; plan.signature = signature(s); record(s, 'note', `Drawing revision ${revision(plan.version)} was issued for review in this sample.`, 'project'); }, 'The edition is issued for review. It has not been approved or released for purchase.'); });
      on(ctx, '[data-open-install]', 'click', () => { write(ctx, (s, c) => { c.schedulePanel = 'install'; }); ctx.go('schedule'); });
    }
  });

  function approvalArtifact(ctx, request) {
    const e = ctx.escape;
    const artifact = request.artifact;
    return `<div class="core-artifact"><div class="core-artifact-plate"><img src="assets/room.png" alt="Room direction attached to this issued approval edition" width="1536" height="1024"><span>RP-024 / Rev ${revision(artifact.version)}</span></div><div><p class="annotation">The exact edition under review</p><h2>${e(artifact.title)}</h2><p>Issued ${e(artifact.date)}. This copy is frozen with the request.</p><ul class="core-artifact-items">${artifact.snapshot.pieces.map(piece => `<li>${piece.quantity} × ${e(piece.name)} <span>${e(piece.material)}</span>${piece.com ? '<span>Studio-supplied material / maker acceptance pending</span>' : ''}${piece.customBrief ? `<span>Commission brief: ${e(piece.customBrief)}</span>` : ''}</li>`).join('')}</ul><p class="small quiet">${artifact.snapshot.finish ? `Chair finish in this edition: ${finishNames[artifact.snapshot.finish]}.` : 'A chair finish is not included in this edition.'}</p></div></div>`;
  }

  function approvalForm(ctx, c) {
    const artifact = latestIssued(c);
    const e = ctx.escape;
    return `<div class="spread"><form id="core-approval-create" class="paper core-approval-draft"><p class="annotation">A request with evidence</p><h2>What needs their approval?</h2><label class="field">Issued artifact<select name="artifact" required>${artifact ? `<option value="${artifact.version}">${e(artifact.title)} / Rev ${revision(artifact.version)} · issued</option>` : '<option value="">No issued artifact available</option>'}<option disabled>Working specification · draft, cannot be used</option></select></label><div class="form-grid"><label class="field">Live project phase<select name="phase"><option>Specifications &amp; approvals</option><option disabled>Design direction · completed</option></select></label><label class="field">Reply due (by the approval milestone)<input type="date" name="due" value="${c.approvalDue}" min="2026-10-22" max="${c.approvalDue}" required></label></div><label class="field">Request title<input name="title" value="Living room direction" required></label><label class="field">The approval question<textarea name="question" rows="2" required>Do you approve the layout and material direction shown in this issued edition?</textarea></label><label class="field">Why this matters<textarea name="why" rows="2">This gives us one agreed direction to carry into the workshop conversations.</textarea></label><details class="details"><summary>Scope and impact</summary><label class="field">What this approval authorizes<textarea name="scope" rows="3">Design direction only. This does not authorize purchasing, payment or workshop production.</textarea></label><div class="core-impact-inputs"><label class="field">Cost change, USD<input type="number" name="cost" value="0" step="1"></label><label class="field">Schedule change, days<input type="number" name="schedule" value="0" step="1"></label><label class="field">Lead-time change, days<input type="number" name="lead" value="0" step="1"></label></div></details><p class="core-form-hold ${c.authorityAssigned ? 'status good' : 'status wait'}">${c.authorityAssigned ? 'Nora Ellis is the designated decision lead.' : 'Assign Nora as decision lead before creating this request.'}</p><button type="submit" class="button" ${!c.authorityAssigned || !artifact ? 'disabled' : ''}>Create approval draft</button></form><aside class="margin-note core-approval-side"><p class="annotation">Who can decide</p><h2>One lead.<br>Two readers.</h2><dl class="core-facts"><div><dt>Decision lead</dt><dd>Nora Ellis</dd></div><div><dt>Required reviewers</dt><dd>Nora Ellis<br>Evan Ellis</dd></div></dl>${!c.authorityAssigned ? '<button type="button" class="button secondary" data-assign-authority>Assign Nora as decision lead</button>' : '<p class="status good">Decision authority assigned</p>'}<p>Each reviewer confirms the same issued artifact before the studio can issue the approval request. Nora then records the decision.</p><button type="button" class="text-button" data-open-plans>Read the issued drawing sets ↗</button></aside></div>`;
  }

  function approvalRequest(ctx, c) {
    const e = ctx.escape;
    const a = c.approval;
    const count = Number(a.reviewers.nora) + Number(a.reviewers.evan);
    const changed = a.signature !== signature(ctx.state) || (c.changedSinceApproval && a.status === 'responded' && a.outcome === 'approved');
    const latest = latestIssued(c);
    const newer = latest && latest.version > a.artifact.version;
    const label = { draft: 'Draft / review confirmations needed', pending: 'Issued / awaiting Nora’s decision', responded: a.outcome === 'approved' ? 'This edition was approved' : 'Changes requested', withdrawn: 'Withdrawn / evidence retained' }[a.status];
    return `${changed ? '<div class="core-change-band"><strong>The current selection has changed.</strong><p>The earlier evidence remains below. Issue a new edition and request a new review before treating the current design as approved.</p><button type="button" class="text-button" data-open-plans>Open drawing revisions ↗</button></div>' : ''}<div class="spread core-gate-layout"><article class="core-gate-paper"><div class="core-section-head"><p class="status ${a.status === 'responded' && a.outcome === 'approved' ? 'good' : 'wait'}">${label}</p><span class="small quiet">Reply due ${day(a.due)}</span></div>${approvalArtifact(ctx, a)}<div class="core-approval-question"><p class="annotation">The question</p><h2>${e(a.question)}</h2><p class="core-authored">${e(a.why)} <span>— Leah</span></p></div><div class="core-scope-impact"><div><h3>What this settles</h3><p>${e(a.scope)}</p></div><div><h3>The impact</h3><p>${ctx.money(a.cost)} cost change<br>${a.schedule} days schedule change<br>${a.lead} days lead-time change</p></div></div><div class="core-confirmation-record"><h3>Review of this exact edition</h3><div><span>Nora Ellis / decision lead</span><strong class="status ${a.reviewers.nora ? 'good' : 'wait'}">${a.reviewers.nora ? 'Review confirmed' : 'Not confirmed'}</strong></div><div><span>Evan Ellis / reviewer</span><strong class="status ${a.reviewers.evan ? 'good' : 'wait'}">${a.reviewers.evan ? 'Review confirmed' : 'Not confirmed'}</strong></div></div>${a.status === 'responded' ? `<div class="core-decision-seal"><p class="annotation">Nora’s recorded decision / 21 October</p><h2>${a.outcome === 'approved' ? 'Approved for this edition.' : 'Please revise this edition.'}</h2>${a.response ? `<p>${e(a.response)}</p>` : ''}<p class="small">${ctx.state.designApproved ? 'The current design approval is on the record.' : 'This historical decision does not approve the current selection.'} Purchasing remains a separate authorization.</p></div>` : ''}${a.status === 'withdrawn' ? `<p class="core-withdrawal">Withdrawal reason: ${e(a.withdrawReason)}</p>` : ''}</article><aside class="margin-note core-gate-margin"><p class="annotation">The next named act</p><h2>${a.status === 'draft' ? count === 2 ? 'Ready to issue.' : 'Let them read it.' : a.status === 'pending' ? 'Nora has the decision.' : 'Keep the evidence.'}</h2>${a.status === 'draft' ? `<p>${count} of 2 frozen reviewers have confirmed revision ${revision(a.artifact.version)}. The studio cannot issue the request until both have read it.</p><details class="details core-client-review" ${count < 2 ? 'open' : ''}><summary>Client review preview</summary><form id="core-confirm-review"><label class="field">Read as<select name="reviewer"><option value="nora">Nora Ellis</option><option value="evan">Evan Ellis</option></select></label><label class="core-check"><input type="checkbox" name="confirmed" required><span>I reviewed ${e(a.artifact.title)}, revision ${revision(a.artifact.version)}.</span></label><button type="submit" class="button secondary">Confirm this review</button></form></details><button type="button" class="button core-full" data-issue-approval ${count < 2 ? 'disabled' : ''}>Issue approval request</button>` : a.status === 'pending' ? `<p>The request is issued. The decision lead responds to the same frozen evidence.</p><details class="details" open><summary>Nora’s decision preview</summary><form id="core-approval-response"><fieldset><legend>My decision on this edition</legend><label class="core-check"><input type="radio" name="outcome" value="approved" required><span>Approve this edition</span></label><label class="core-check"><input type="radio" name="outcome" value="changes" required><span>Request changes</span></label></fieldset><label class="field">A note to Leah<textarea name="response" rows="3" placeholder="Required when requesting changes"></textarea></label><button type="submit" class="button">Record Nora’s decision</button></form></details>` : `<p>A decision stays with its issued artifact. A new edition needs a new review.</p>${a.status === 'withdrawn' ? '<button type="button" class="button secondary" data-new-approval>Start another request</button>' : newer ? `<button type="button" class="button secondary" data-supersede>Create superseding draft / Rev ${revision(latest.version)}</button>` : '<button type="button" class="text-button" data-open-plans>Prepare a new issued revision ↗</button>'}`}${['draft', 'pending'].includes(a.status) ? `<details class="details core-withdraw"><summary>Withdraw this request</summary><form id="core-withdraw"><label class="field">Reason for withdrawal<textarea name="reason" rows="2" required></textarea></label><button type="submit" class="text-button">Withdraw and retain the evidence</button></form></details>` : ''}<p class="small quiet core-after-action">A design decision does not authorize a purchase or release a workshop order.</p></aside></div>`;
  }

  RoomProof.register('approvals', {
    title: 'Client approvals', family: 'project',
    render(ctx) {
      const c = initials(ctx);
      return title('Lake Mendota House / The decision record', 'A clear yes,<br>to an exact edition.', 'The evidence, the people who reviewed it, and the decision they made stay on the same page.') + (c.approval ? approvalRequest(ctx, c) : approvalForm(ctx, c)) + (c.approvalHistory.length ? `<section class="core-prior-editions"><h2>Earlier requests</h2>${c.approvalHistory.map(a => `<details class="details core-history-entry"><summary>Rev ${revision(a.artifact.version)} · ${ctx.escape(a.title)} · ${a.status === 'responded' ? a.outcome === 'approved' ? 'Approved / superseded' : 'Changes requested / superseded' : a.status}</summary>${approvalArtifact(ctx, a)}<p><strong>Question:</strong> ${ctx.escape(a.question)}</p><p><strong>Review confirmations:</strong> Nora ${a.reviewers.nora ? 'confirmed' : 'not confirmed'}; Evan ${a.reviewers.evan ? 'confirmed' : 'not confirmed'}.</p>${a.response ? `<p><strong>Nora’s response:</strong> ${ctx.escape(a.response)}</p>` : ''}${a.withdrawReason ? `<p><strong>Withdrawal:</strong> ${ctx.escape(a.withdrawReason)}</p>` : ''}<p class="small quiet">Historical evidence only. This request does not approve the current selection.</p></details>`).join('')}</section>` : '');
    },
    bind(ctx) {
      on(ctx, '[data-assign-authority]', 'click', () => write(ctx, (s, c) => { c.authorityAssigned = true; }, 'Nora Ellis is the designated decision lead. Evan remains a required reviewer.'));
      on(ctx, '[data-open-plans]', 'click', () => { write(ctx, (s, c) => { c.projectPanel = 'plans'; }); ctx.go('project'); });
      on(ctx, '#core-approval-create', 'submit', event => { const d = formData(event); const c = initials(ctx); const artifact = latestIssued(c); if (!c.authorityAssigned || !artifact) return; write(ctx, (s, next) => { next.approval = { id: `APR-024-${artifact.version}`, title: d.get('title').trim(), question: d.get('question').trim(), why: d.get('why').trim(), scope: d.get('scope').trim(), due: d.get('due'), cost: Number(d.get('cost')) || 0, schedule: Number(d.get('schedule')) || 0, lead: Number(d.get('lead')) || 0, phase: d.get('phase'), status: 'draft', reviewers: { nora: false, evan: false }, artifact: JSON.parse(JSON.stringify(artifact)), signature: artifact.signature }; record(s, 'approval', `An approval draft was prepared for drawing revision ${revision(artifact.version)}.`, 'approvals'); }, 'Draft created. Both reviewers must confirm the exact issued edition before it can be issued.'); });
      on(ctx, '#core-confirm-review', 'submit', event => { const d = formData(event); if (!d.get('confirmed')) return; write(ctx, (s, c) => { c.approval.reviewers[d.get('reviewer')] = true; record(s, 'approval', `${d.get('reviewer') === 'nora' ? 'Nora' : 'Evan'} confirmed review of revision ${revision(c.approval.artifact.version)}.`, 'approvals'); }, 'Review confirmation recorded against this exact edition.'); });
      on(ctx, '[data-issue-approval]', 'click', () => { const a = initials(ctx).approval; if (!a || a.status !== 'draft' || !a.reviewers.nora || !a.reviewers.evan) return; write(ctx, (s, c) => { c.approval.status = 'pending'; record(s, 'approval', `The approval request for revision ${revision(c.approval.artifact.version)} was issued to Nora in this sample.`, 'approvals'); }, 'The request is issued in this sample. Nora’s decision is now the next act.'); });
      on(ctx, '#core-approval-response', 'submit', event => { const d = formData(event); if (d.get('outcome') === 'changes' && !d.get('response').trim()) { ctx.feedback('Add a note explaining the requested changes.'); return; } write(ctx, (s, c) => { const a = c.approval; a.status = 'responded'; a.outcome = d.get('outcome'); a.response = d.get('response').trim(); if (a.outcome === 'approved') s.clientFinish = a.artifact.snapshot.finish; const current = a.signature === signature(s); s.designApproved = a.outcome === 'approved' && current; c.changedSinceApproval = a.outcome === 'approved' && !current; record(s, 'approval', `Nora ${a.outcome === 'approved' ? 'approved' : 'requested changes to'} drawing revision ${revision(a.artifact.version)}.`, 'approvals'); }, 'Nora’s decision is recorded with its issued evidence. Purchase authority is unchanged.'); });
      on(ctx, '#core-withdraw', 'submit', event => { const d = formData(event); write(ctx, (s, c) => { c.approval.status = 'withdrawn'; c.approval.withdrawReason = d.get('reason').trim(); record(s, 'approval', `The approval request was withdrawn: ${d.get('reason').trim()}`, 'approvals'); }, 'Request withdrawn. The edition, confirmations and reason remain in the record.'); });
      on(ctx, '[data-new-approval]', 'click', () => write(ctx, (s, c) => { c.approvalHistory.unshift(c.approval); c.approval = null; }));
      on(ctx, '[data-supersede]', 'click', () => { const c = initials(ctx); const artifact = latestIssued(c); if (!artifact || artifact.version <= c.approval.artifact.version) return; write(ctx, (s, next) => { const previous = next.approval; next.approvalHistory.unshift(previous); next.approval = { ...previous, id: `APR-024-${artifact.version}`, artifact: JSON.parse(JSON.stringify(artifact)), signature: artifact.signature, status: 'draft', outcome: null, response: '', due: next.approvalDue, reviewers: { nora: false, evan: false } }; s.designApproved = false; record(s, 'approval', `A superseding approval draft was created for revision ${revision(artifact.version)}.`, 'approvals'); }, 'The new edition needs both review confirmations. The earlier decision is retained.'); });
    }
  });

  const agreementChecks = a => [
    ['A linked client with an email', a.clientLinked],
    ['The services and room are named', Boolean(a.scope.trim())],
    ['An hourly rate with a fee ceiling', a.hourly > 0 && a.ceiling > 0],
    ['The retainer is within the fee ceiling', a.retainer >= 0 && a.retainer <= a.ceiling],
    ['The client can see the fee basis', a.feeVisible]
  ];

  function agreementEdition(ctx, a) {
    const e = ctx.escape;
    return `<article class="core-agreement-edition"><div class="core-letterhead"><span>Middle West<br>Studio</span><span>Design services<br>Madison, Wisconsin</span></div><p class="annotation">Prepared for Nora &amp; Evan Ellis / 21 October 2026</p><h2>A considered room.<br>A clear engagement.</h2><p class="core-agreement-address">Lake Mendota House<br>Living room</p><section class="core-clause"><span>01</span><div><h3>The work we will do</h3><p>${e(a.scope)}</p></div></section><section class="core-clause"><span>02</span><div><h3>The fee basis</h3>${a.feeVisible ? `<p>Time is billed at <strong>${ctx.money(a.hourly)} per hour</strong>, up to a design-services ceiling of <strong>${ctx.money(a.ceiling)}</strong>. We will agree any additional services before proceeding.</p><p>A design-services retainer of ${ctx.money(a.retainer)} is due on acceptance. Furniture, freight and estimated tax sit in the separate project account.</p>` : '<p class="status wait">The fee basis is not visible in this draft. It must be restored before this agreement can be issued.</p>'}</div></section><section class="core-clause"><span>03</span><div><h3>Working together</h3><p>Nora is the intended decision lead. Project authority is assigned before an approval request; Nora and Evan review the issued design together. Furniture orders require their own authorization.</p><p>The installation target is ${day(a.target || initials(ctx).brief.target)}. Workshop and delivery dates will be confirmed separately.</p></div></section><section class="core-clause"><span>04</span><div><h3>Before work begins</h3><p>Review the scope and fee basis, then return an accepted agreement. This specimen remains ${a.status === 'issued' ? 'awaiting client acceptance' : 'in draft'}.</p></div></section><div class="core-agreement-signoff"><p>Prepared by Leah<br><span>Middle West Studio</span></p><p>For Nora &amp; Evan Ellis<br><span>${a.status === 'issued' ? 'Awaiting acceptance' : 'Draft for review'}</span></p></div><p class="small quiet">Design agreement specimen · not an executed contract</p></article>`;
  }

  function agreementDraft(ctx, c) {
    const e = ctx.escape;
    const a = c.agreement;
    const checks = agreementChecks(a);
    const ready = checks.every(([, passed]) => passed);
    const issued = a.status === 'issued';
    const client = c.agreementMode === 'client';
    return `<div class="core-engagement-tools"><p class="status ${issued ? 'good' : ready ? 'good' : 'wait'}">${issued ? 'Issued copy / awaiting client acceptance' : ready ? 'Draft / ready for a final read' : 'Draft / complete the held parts'}</p><div role="group" aria-label="Agreement edition"><button type="button" class="text-button" data-agreement-mode="studio" aria-pressed="${!client}">Studio working copy</button><button type="button" class="text-button" data-agreement-mode="client" aria-pressed="${client}">Client’s edition</button></div></div><div class="core-engagement-spread">${client || issued ? agreementEdition(ctx, a.issuedCopy || a) : `<form id="core-agreement-form" class="core-agreement-working"><div class="core-letterhead"><span>Middle West<br>Studio</span><span>Services agreement<br>Draft 01 / Lake Mendota House</span></div><section class="core-agreement-part"><div><span class="annotation">Part 01</span><h2>The services.</h2></div><label class="field">Scope of design services<textarea name="scope" rows="4" required>${e(a.scope)}</textarea></label><p class="small quiet">Living room · one room in the engagement</p></section><section class="core-agreement-part"><div><span class="annotation">Part 02</span><h2>A named fee,<br>with a limit.</h2></div><div class="core-fee-grid"><label class="field">Hourly rate, USD<input type="number" name="hourly" min="0" step="1" value="${a.hourly}" required></label><label class="field">Design-services ceiling, USD<input type="number" name="ceiling" min="0" step="1" value="${a.ceiling}" required></label><label class="field">Services retainer, USD<input type="number" name="retainer" min="0" step="1" value="${a.retainer}" required></label></div><p class="small quiet">The services retainer is separate from the sample furnishings deposit. Editing this draft records no payment.</p></section><section class="core-agreement-part"><div><span class="annotation">Part 03</span><h2>The people<br>and the terms.</h2></div><p>Nora Ellis is the intended client. Evan Ellis also reviews the design. Purchase authority remains outside this agreement.</p><details class="details"><summary>Client link and fee visibility</summary><label class="core-check"><input type="checkbox" name="clientLinked" ${a.clientLinked ? 'checked' : ''}><span>Nora’s client account is linked with an email</span></label><label class="core-check"><input type="checkbox" name="feeVisible" ${a.feeVisible ? 'checked' : ''}><span>Include the fee basis in the client’s edition</span></label><p class="small quiet">Studio owner controls shown for this sample.</p></details></section><div class="core-agreement-save"><button type="submit" name="action" value="save" class="button secondary">Save the parts</button><button type="submit" name="action" value="review" class="button">Save &amp; review</button></div></form>`}<aside class="core-engagement-margin margin-note"><p class="annotation">${client ? 'The client sees' : 'Before it leaves the studio'}</p><h2>${issued ? 'The issued copy is kept.' : client ? 'A readable agreement.' : 'Every part, accounted for.'}</h2>${issued ? `<p>The scope and fees shown here were frozen when this copy was issued.</p><p class="status wait">Client acceptance has not been recorded.</p><p class="small quiet">The sample records the issue locally. No email has been sent and no retainer collected.</p><a class="text-button" href="${ctx.link('accounts')}" data-go="accounts">Read the project account ↗</a>` : `<ul class="core-readiness">${checks.map(([label, passed]) => `<li><span aria-hidden="true">${passed ? '✓' : '—'}</span><span>${label}</span><strong class="status ${passed ? 'good' : 'wait'}">${passed ? 'Ready' : 'Held'}</strong></li>`).join('')}</ul>${client ? '<p>The client’s edition includes the saved scope, fee basis and working terms. Private studio notes and supplier costs are excluded.</p><button type="button" class="button secondary" data-agreement-mode="studio">Return to the working copy</button>' : '<p>Save the parts before the final read. An hourly agreement needs a ceiling, and its fee basis must be visible to the client.</p>'}`}${c.agreementReview && !issued && !client ? `<section class="core-agreement-review"><p class="annotation">Final read / saved edition</p><h3>Ready for Nora’s inbox?</h3><p>${e(a.scope)}</p><p>${ctx.money(a.hourly)} / hour · ceiling ${ctx.money(a.ceiling)}<br>Services retainer ${ctx.money(a.retainer)}</p><form id="core-agreement-issue"><label class="field">A personal message<textarea name="message" rows="5" maxlength="1500" required>${e(a.message)}</textarea></label><p class="small quiet">This offer is valid for 14 days. Issue records are kept with the agreement.</p><button type="submit" class="button" ${ready ? '' : 'disabled'}>Issue agreement</button>${ready ? '' : '<p class="status wait">Resolve the held parts before issuing.</p>'}</form></section>` : ''}</aside></div>`;
  }

  RoomProof.register('engagement', {
    title: 'Design agreement', family: 'project',
    render(ctx) { const c = initials(ctx); return title('Lake Mendota House / Design services', 'Before the work,<br>an understanding.', 'The services, the fee basis and the client’s copy are composed together. A draft becomes an issued agreement only after its parts are ready.') + agreementDraft(ctx, c); },
    bind(ctx) {
      on(ctx, '[data-agreement-mode]', 'click', event => write(ctx, (s, c) => { c.agreementMode = event.currentTarget.dataset.agreementMode; }));
      on(ctx, '#core-agreement-form', 'input', () => { const button = ctx.root.querySelector('#core-agreement-issue button'); if (button) { button.disabled = true; ctx.feedback('The working parts have changed. Save & review again before issuing.'); } });
      on(ctx, '#core-agreement-form', 'submit', event => {
        const action = event.submitter?.value || 'save'; const d = formData(event);
        write(ctx, (s, c) => { Object.assign(c.agreement, { scope: d.get('scope').trim(), hourly: Number(d.get('hourly')), ceiling: Number(d.get('ceiling')), retainer: Number(d.get('retainer')), clientLinked: Boolean(d.get('clientLinked')), feeVisible: Boolean(d.get('feeVisible')) }); c.agreementReview = action === 'review'; record(s, 'note', 'The design-services agreement scope and fee basis were saved in draft.', 'engagement'); }, action === 'review' ? 'The saved edition is ready for its final read. Any held parts remain listed.' : 'The agreement parts are saved in draft.');
      });
      on(ctx, '#core-agreement-issue', 'submit', event => {
        const d = formData(event); const a = initials(ctx).agreement;
        if (a.status !== 'draft' || !agreementChecks(a).every(([, passed]) => passed)) return;
        write(ctx, (s, c) => { c.agreement.message = d.get('message').trim(); c.agreement.status = 'issued'; c.agreement.issuedCopy = { scope: a.scope, hourly: a.hourly, ceiling: a.ceiling, retainer: a.retainer, feeVisible: true, status: 'issued', issuedDate: '21 October 2026', target: c.brief.target }; c.agreementReview = false; record(s, 'note', 'The design-services agreement was issued locally and is awaiting client acceptance.', 'engagement'); }, 'Agreement issued in this sample. No email was sent, acceptance recorded or payment collected.');
      });
    }
  });

  function scheduleFacts(c, due = c.approvalDue) {
    const ready = addDays(due, 20);
    return { ready, overrun: Math.max(0, daysBetween(c.brief.target, ready)), slack: daysBetween(ready, c.brief.target) };
  }

  function schedulePlan(ctx, c) {
    const e = ctx.escape;
    const facts = scheduleFacts(c);
    const preview = c.schedulePreview;
    const candidate = preview ? scheduleFacts(c, preview.date) : null;
    const delta = preview ? daysBetween(c.approvalDue, preview.date) : 0;
    return `<div class="core-schedule-spread"><article class="core-schedule-document"><div class="core-schedule-lead"><p class="annotation">Four phases / one anchored target</p><div class="core-target-date"><span>${Number(c.brief.target.slice(8))}</span><div>${day(c.brief.target).split(' ').slice(1).join(' ')}<small>Installation target · 2026</small></div></div><p>The plan keeps the date you promised visible when another date moves.</p></div><ol class="core-phases"><li class="core-phase core-phase-complete"><div class="core-phase-number">01</div><div><p class="annotation">12–21 October</p><h2>Design direction</h2><p class="quiet">Brief, room study and the first issued drawing.</p></div><span class="status good">Completed</span></li><li class="core-phase core-phase-active"><div class="core-phase-number">02</div><div><p class="annotation">22 October – ${day(c.approvalDue)}</p><h2>Specifications<br>&amp; approvals</h2><p>${ctx.state.designApproved ? 'The current design edition has a recorded approval.' : 'The formal design decision is still open.'}</p><a class="text-button" href="${ctx.link('approvals')}" data-go="approvals">Read the approval record ↗</a>${c.approval && c.approval.due !== c.approvalDue ? `<p class="status wait">The existing request’s reply deadline remains ${day(c.approval.due)}. Review this mismatch with the client; moving the milestone does not rewrite an issued request.</p>` : ''}${preview ? `<p class="core-date-ghost">Proposed milestone · ${day(preview.date)} (${delta >= 0 ? '+' : ''}${delta} days)</p>` : ''}</div><span class="status ${ctx.state.designApproved ? 'good' : 'wait'}">${ctx.state.designApproved ? 'Decision recorded' : 'Active'}</span></li><li class="core-phase"><div class="core-phase-number">03</div><div><p class="annotation">After approval / 20-day planning allowance</p><h2>Workshop<br>&amp; delivery</h2><p>Planning allowance ends ${day(facts.ready)}. Workshop dates remain unconfirmed.</p><p class="status wait">${ctx.state.purchaseAuthorized ? 'Purchasing authorized separately · release review still required' : 'Purchase authorization still required'}</p>${preview ? `<p class="core-date-ghost">Allowance would end ${day(candidate.ready)}</p>` : ''}<a class="text-button" href="${ctx.link('orders')}" data-go="orders">Read the order holds ↗</a></div><span class="status wait">Planned</span></li><li class="core-phase core-phase-anchor"><div class="core-phase-number">04</div><div><p class="annotation">${day(c.brief.target)} / fixed target</p><h2>At the house</h2><p>${facts.overrun ? `The current allowance passes this target by ${facts.overrun} ${facts.overrun === 1 ? 'day' : 'days'}. Resolve timing with the workshop before promising delivery.` : `${facts.slack} ${facts.slack === 1 ? 'day' : 'days'} between the planning allowance and installation target.`}</p><button type="button" class="text-button" data-schedule-panel="install">Open the installation work ↗</button></div><span class="status ${facts.overrun ? 'wait' : ''}">${facts.overrun ? 'Timing conflict' : 'Anchored'}</span></li></ol></article><aside class="core-schedule-margin margin-note"><p class="annotation">Adjust the milestone</p><h2>A date moves.<br>See what follows.</h2><form id="core-date-preview"><label class="field">Design approval milestone<input type="date" name="date" value="${preview ? preview.date : c.approvalDue}" min="2026-10-22" required></label><p class="small quiet">Preview the change before writing it into the plan. The installation target stays anchored.</p><button type="submit" class="button secondary">Preview date change</button></form>${preview ? `<section class="core-date-confirm"><p class="annotation">Proposed change / not yet saved</p><h3>${day(c.approvalDue)} <span aria-hidden="true">→</span> ${day(preview.date)}</h3><dl class="core-facts"><div><dt>Planning allowance ends</dt><dd>${day(candidate.ready)}</dd></div><div><dt>Installation target</dt><dd>${day(c.brief.target)} · unchanged</dd></div><div><dt>Effect on the target</dt><dd>${candidate.overrun ? `${candidate.overrun} ${candidate.overrun === 1 ? 'day' : 'days'} past the target` : `${candidate.slack} ${candidate.slack === 1 ? 'day' : 'days'} remain before the target`}</dd></div></dl><form id="core-date-confirm">${candidate.overrun ? '<p class="status wait">This change crosses the held installation target. Choose an earlier milestone before committing.</p>' : ''}<label class="field">Reason for the change<textarea name="reason" rows="3" required>Adjust the design review milestone and its planning allowance.</textarea></label><button type="submit" class="button" ${candidate.overrun ? 'disabled' : ''}>Confirm date change</button><button type="button" class="text-button" data-cancel-date>Discard preview</button></form></section>` : ''}<div class="core-source-note"><h3>Planning, not a delivery promise.</h3><p class="small quiet">The 20-day allowance is a sample planning assumption. It is not a maker-confirmed lead time, order release or installation booking.</p></div></aside></div>${openItemSection(ctx, c)}`;
  }

  function openItemSection(ctx, c) {
    const e = ctx.escape;
    const count = c.openItems.filter(item => !item.done).length;
    return `<section class="core-open-items"><div class="core-section-head"><div><p class="annotation">Coordination / current phase</p><h2>${count} open ${count === 1 ? 'item' : 'items'}.</h2></div><span class="small quiet">A named person and a due date</span></div><ul class="core-task-list">${c.openItems.map(item => `<li><label class="core-check"><input type="checkbox" data-open-item="${e(item.id)}" ${item.done ? 'checked' : ''}><span><strong>${e(item.title)}</strong><small>${e(item.owner)} · ${day(item.date)}</small></span></label><span class="status ${item.done ? 'good' : 'wait'}">${item.done ? 'Done' : 'Open'}</span></li>`).join('')}</ul><details class="details core-add-item"><summary>New open item</summary><form id="core-open-item-add"><label class="field">What needs to happen<input name="title" required maxlength="180"></label><div class="form-grid"><label class="field">Owner<select name="owner"><option>Leah</option><option>Nora</option><option>Evan</option></select></label><label class="field">Due date<input type="date" name="date" value="2026-10-26" required></label></div><button type="submit" class="button secondary">Add open item</button></form></details></section>`;
  }

  function scheduleInstall(ctx, c) {
    const e = ctx.escape;
    const done = c.punch.filter(task => task.done).length;
    return `<div class="core-install-spread"><article class="core-punch-document"><div class="core-install-letterhead"><p class="annotation">Field copy / Lake Mendota House</p><span>${day(c.brief.target)}</span></div><h2>The last inch<br>of the room.</h2><p class="lede">Installation work belongs to the room and the day. Keep each check small enough to finish and clear enough to hand over.</p><div class="core-punch-count"><strong>${done} <span>/ ${c.punch.length}</span></strong><p>checks complete<br><span>${c.punch.reduce((sum, task) => sum + Number(task.hours), 0).toLocaleString('en-US', { maximumFractionDigits: 2 })} hours estimated</span></p></div><ul class="core-task-list core-punch-list">${c.punch.map(task => `<li><label class="core-check"><input type="checkbox" data-punch="${e(task.id)}" ${task.done ? 'checked' : ''}><span><strong>${e(task.title)}</strong><small>${day(task.date)} · ${Number(task.hours).toLocaleString('en-US', { maximumFractionDigits: 2 })} hours estimated</small></span></label><span class="status ${task.done ? 'good' : 'wait'}">${task.done ? 'Done' : 'Open'}</span></li>`).join('')}</ul><details class="details core-add-item"><summary>Add an installation check</summary><form id="core-punch-add"><label class="field">The work to finish<input name="title" maxlength="180" required></label><div class="form-grid"><label class="field">Day<input type="date" name="date" value="${e(c.brief.target)}" required></label><label class="field">Estimate, hours<input type="number" name="hours" value="0.25" min="0.25" max="24" step="0.25" required></label></div><button type="submit" class="button secondary">Add installation check</button></form></details></article><aside class="core-install-margin"><figure><img src="assets/room.png" alt="Living room concept illustration used as a direction reference for installation" width="1536" height="1024"><figcaption>Direction reference · not an installation photograph</figcaption></figure><div class="margin-note"><p class="annotation">Evidence at closeout</p><h2>A check is not<br>a site photograph.</h2><p>This field copy has no installation photographs or measured scan attached. Completed checks record the work only.</p><p class="status wait">Project closeout remains open</p><a class="text-button" href="${ctx.link('hours')}" data-go="hours">Record the time in Timesheets ↗</a><button type="button" class="text-button" data-schedule-panel="plan">Return to phases and dates ↗</button></div></aside></div>`;
  }

  RoomProof.register('schedule', {
    title: 'Project schedule', family: 'project',
    render(ctx) { const c = initials(ctx); return title('Lake Mendota House / The working schedule', 'Time, with<br>consequences.', 'The current phase, the next decision and the installation target stay connected. Preview a changed date before it becomes the plan.') + panelNav(c.schedulePanel, [['plan', 'Phases & dates'], ['install', 'Installation work']], 'data-schedule-panel') + (c.schedulePanel === 'install' ? scheduleInstall(ctx, c) : schedulePlan(ctx, c)); },
    bind(ctx) {
      on(ctx, '[data-schedule-panel]', 'click', event => write(ctx, (s, c) => { c.schedulePanel = event.currentTarget.dataset.schedulePanel; }));
      on(ctx, '#core-date-preview input', 'input', () => { const button = ctx.root.querySelector('#core-date-confirm button[type=submit]'); if (button) { button.disabled = true; ctx.feedback('Preview the changed date before confirming it.'); } });
      on(ctx, '#core-date-preview', 'submit', event => { const d = formData(event); if (d.get('date') === initials(ctx).approvalDue) { ctx.feedback('That is the current milestone date. Choose another date to preview its effect.'); return; } write(ctx, (s, c) => { c.schedulePreview = { date: d.get('date') }; }, 'Preview only. The stored dates have not changed.'); });
      on(ctx, '[data-cancel-date]', 'click', () => write(ctx, (s, c) => { c.schedulePreview = null; }, 'The date preview was discarded. The current plan is unchanged.'));
      on(ctx, '#core-date-confirm', 'submit', event => { const d = formData(event); const c = initials(ctx); if (!c.schedulePreview) return; if (ctx.root.querySelector('#core-date-preview input').value !== c.schedulePreview.date) { ctx.feedback('Preview the changed date before confirming it.'); return; } const next = scheduleFacts(c, c.schedulePreview.date); if (next.overrun) { ctx.feedback('This change crosses the held installation target and cannot be committed.'); return; } write(ctx, (s, value) => { const previous = value.approvalDue; value.approvalDue = value.schedulePreview.date; value.schedulePreview = null; record(s, 'schedule', `The design approval milestone moved from ${day(previous)} to ${day(value.approvalDue)}.${next.overrun ? ` The installation target stays ${day(value.brief.target)}; a ${next.overrun}-day planning conflict needs follow-up.` : ' The installation target is unchanged.'} Reason: ${d.get('reason').trim()}`, 'schedule'); }, 'The milestone is saved. The installation target remains anchored.'); });
      on(ctx, '[data-open-item]', 'change', event => { const node = event.currentTarget; write(ctx, (s, c) => { const item = c.openItems.find(value => value.id === node.dataset.openItem); item.done = node.checked; record(s, 'schedule', `${item.done ? 'Completed' : 'Reopened'}: ${item.title}.`, 'schedule'); }); });
      on(ctx, '#core-open-item-add', 'submit', event => { const d = formData(event); write(ctx, (s, c) => { c.openItems.push({ id: `open-${Date.now()}`, title: d.get('title').trim(), owner: d.get('owner'), date: d.get('date'), done: false }); record(s, 'schedule', `An open item was assigned to ${d.get('owner')}: ${d.get('title').trim()}.`, 'schedule'); }, 'The open item is on the current phase.'); });
      on(ctx, '[data-punch]', 'change', event => { const node = event.currentTarget; write(ctx, (s, c) => { const item = c.punch.find(value => value.id === node.dataset.punch); item.done = node.checked; record(s, 'schedule', `${item.done ? 'Completed' : 'Reopened'} installation check: ${item.title}.`, 'schedule'); }); });
      on(ctx, '#core-punch-add', 'submit', event => { const d = formData(event); write(ctx, (s, c) => { c.punch.push({ id: `punch-${Date.now()}`, title: d.get('title').trim(), date: d.get('date'), hours: Number(d.get('hours')), done: false }); record(s, 'schedule', `An installation check was added: ${d.get('title').trim()}.`, 'schedule'); }, 'The installation check is saved with its date and estimate.'); });
    }
  });
})();
